const updateItemsInPackage = method.getMethod('updateItemsInPackage')?.method;
if (!updateItemsInPackage) {
	return;
}

const { itemTypeName, itemId } = options;
const itemKeyedName = window.aras.getKeyedName(itemId, itemTypeName);
const formItems = [{ id: itemId, name: itemKeyedName }];

await updateItemsInPackage(formItems, itemTypeName);
